// TLS through the chaos proxy, without contacting production: a local package:grpc server with a self-signed
// certificate stands in for the backend, and the client reaches it through the proxy with the channel the kit uses
// for checks 2 and 3 (`proxiedGrpcChannel`): it dials the proxy, but uses the name of the server for SNI, for the
// verification of the certificate and as the authority of the calls.
//
// The certificate is generated by the test with the `openssl` command line tool; the test is skipped without it.

import 'dart:async';
import 'dart:io';

import 'package:grpc/grpc.dart';
import 'package:grpc/grpc_connection_interface.dart' show ClientChannelBase;
import 'package:test/test.dart';

import '../util/chaos_proxy.dart';
import '../util/self_signed_certificate.dart';
import 'verify_production.dart';

/// The name in the certificate. Nothing resolves it: the client only ever dials the proxy on the loopback address.
const String serverName = 'backend.firestore-kit.test';

/// A bidirectional streaming method that echoes every message, and remembers what reached the server.
class _EchoService extends Service {
  _EchoService() {
    $addMethod(
      ServiceMethod<int, int>(
        'Echo',
        (ServiceCall call, Stream<int> requests) {
          authorities.add(call.clientMetadata?[':authority']);
          return requests.map((int value) {
            received.add(value);
            return value;
          });
        },
        true,
        true,
        (List<int> value) => value.isEmpty ? 0 : value.first,
        (int value) => <int>[value],
      ),
    );
  }

  final List<int> received = <int>[];
  final List<String?> authorities = <String?>[];

  @override
  String get $name => 'test.Echo';
}

class _EchoClient extends Client {
  _EchoClient(super.channel);

  static final ClientMethod<int, int> _echo = ClientMethod<int, int>(
    '/test.Echo/Echo',
    (int value) => <int>[value],
    (List<int> value) => value.isEmpty ? 0 : value.first,
  );

  ResponseStream<int> echo(Stream<int> requests) =>
      $createStreamingCall(_echo, requests);
}

/// An open echo call: what came back, and how it ended.
class _Call {
  _Call(_EchoClient client) {
    client.echo(requests.stream).listen(
          responses.add,
          onError: (Object e) {
            error = e;
            if (!done.isCompleted) {
              done.complete();
            }
          },
          onDone: () {
            if (!done.isCompleted) {
              done.complete();
            }
          },
        );
  }

  final StreamController<int> requests = StreamController<int>();
  final List<int> responses = <int>[];
  final Completer<void> done = Completer<void>();
  Object? error;
}

Future<void> _eventually(bool Function() condition, String what,
    {String Function()? describe}) async {
  final Stopwatch watch = Stopwatch()..start();
  while (!condition()) {
    if (watch.elapsed > const Duration(seconds: 10)) {
      fail('Timed out waiting for $what${describe == null ? '' : ': ${describe()}'}');
    }
    await Future<void>.delayed(const Duration(milliseconds: 20));
  }
}

void main() {
  final String? skip = SelfSignedCertificate.unavailableReason;

  late SelfSignedCertificate selfSigned;
  late List<int> certificate;
  late Server server;
  late _EchoService service;
  late ChaosProxy proxy;
  final List<ClientChannelBase> channels = <ClientChannelBase>[];

  setUp(() async {
    selfSigned = SelfSignedCertificate.create(serverName);
    certificate = selfSigned.certificate;

    service = _EchoService();
    server = Server.create(services: <Service>[service]);
    await server.serve(
      address: InternetAddress.loopbackIPv4,
      port: 0,
      security: ServerTlsCredentials(
        certificate: certificate,
        privateKey: selfSigned.privateKey,
      ),
    );
    proxy = await ChaosProxy.start('127.0.0.1', server.port!);
  });

  tearDown(() async {
    proxy.restore();
    for (final ClientChannelBase channel in channels) {
      await channel.terminate();
    }
    channels.clear();
    await proxy.close();
    await server.shutdown();
    selfSigned.delete();
  });

  _EchoClient client({String name = serverName, bool trust = true}) {
    final ClientChannelBase channel = proxiedGrpcChannel(
      proxyHost: proxy.host,
      proxyPort: proxy.port,
      serverName: name,
      ssl: true,
      trustedCertificates: trust ? certificate : null,
    );
    channels.add(channel);
    return _EchoClient(channel);
  }

  group('TLS through the chaos proxy', () {
    test('a client that dials the proxy with the name of the server works',
        () async {
      final _Call call = _Call(client());
      call.requests
        ..add(1)
        ..add(2);
      await _eventually(() => call.responses.length == 2, 'the echoes',
          describe: () => 'error=${call.error} responses=${call.responses} '
              'connections=${proxy.acceptedConnections} up=${proxy.bytesUp} '
              'down=${proxy.bytesDown} received=${service.received}');
      expect(call.responses, <int>[1, 2]);
      await call.requests.close();
      await call.done.future.timeout(const Duration(seconds: 5));
      expect(call.error, isNull);

      // The connection went through the proxy, as TLS (the proxy only saw bytes), and the call carried the name of
      // the server as its authority, not the address of the proxy.
      expect(proxy.acceptedConnections, 1);
      expect(proxy.bytesUp, greaterThan(0));
      expect(service.authorities, <String?>[serverName]);
    });

    test('the certificate is verified against that name', () async {
      // Another name than the one in the certificate: the handshake fails, nothing reaches the server.
      final _Call wrongName = _Call(client(name: 'other.firestore-kit.test'));
      wrongName.requests.add(1);
      await wrongName.done.future.timeout(const Duration(seconds: 20));
      expect(wrongName.error, isA<GrpcError>());

      // The right name, but the self-signed certificate is not trusted (the default roots, as against production).
      final _Call untrusted = _Call(client(trust: false));
      untrusted.requests.add(1);
      await untrusted.done.future.timeout(const Duration(seconds: 20));
      expect(untrusted.error, isA<GrpcError>());

      expect(service.received, isEmpty);
      expect(service.authorities, isEmpty);
    });

    test(
        'answers held back and a cut lose the answer, not the request, and '
        'the next call reconnects', () async {
      final _EchoClient echo = client();
      final _Call first = _Call(echo);
      first.requests.add(1);
      await _eventually(() => first.responses.length == 1, 'the first echo');

      // As checks 2 and 3 do: hold back what the server sends, let the request through, then cut.
      proxy.mode = ChaosMode.stallDown;
      first.requests.add(2);
      await _eventually(
          () => service.received.length == 2, 'the request to reach the server');
      await Future<void>.delayed(const Duration(milliseconds: 200));
      expect(first.responses, <int>[1], reason: 'the answer is held back');
      proxy
        ..cut()
        ..mode = ChaosMode.forward;
      await first.done.future.timeout(const Duration(seconds: 10));
      expect(first.error, isA<GrpcError>());
      expect(first.responses, <int>[1], reason: 'the answer was lost');

      // A new call on the same channel gets a new TLS connection through the proxy.
      final _Call second = _Call(echo);
      second.requests.add(3);
      await _eventually(() => second.responses.length == 1, 'the echo after the cut');
      expect(second.responses, <int>[3]);
      expect(service.received, <int>[1, 2, 3]);
      expect(proxy.acceptedConnections, 2);
      expect(proxy.cuts, 1);
      await second.requests.close();
      await second.done.future.timeout(const Duration(seconds: 5));
    });

    test('requests held back and a cut never reach the server', () async {
      final _EchoClient echo = client();
      final _Call call = _Call(echo);
      call.requests.add(1);
      await _eventually(() => call.responses.length == 1, 'the first echo');

      proxy.mode = ChaosMode.stallUp;
      call.requests.add(2);
      await Future<void>.delayed(const Duration(milliseconds: 300));
      expect(service.received, <int>[1]);
      proxy
        ..cut()
        ..mode = ChaosMode.forward;
      await call.done.future.timeout(const Duration(seconds: 10));
      expect(call.error, isA<GrpcError>());
      expect(service.received, <int>[1]);
    });

    test('a cut in the middle of the encrypted stream ends the call',
        () async {
      final _EchoClient echo = client();
      final _Call call = _Call(echo);
      call.requests.add(1);
      await _eventually(() => call.responses.length == 1, 'the first echo');

      // Cut at the next bytes the server sends: a TLS record is dropped mid-stream.
      final Future<void> cut = proxy.cutOnNext(ChaosDirection.down);
      call.requests.add(2);
      await cut.timeout(const Duration(seconds: 5));
      await call.done.future.timeout(const Duration(seconds: 10));
      expect(call.error, isA<GrpcError>());
      expect(call.responses, <int>[1]);
      expect(service.received, <int>[1, 2]);

      final _Call again = _Call(echo);
      again.requests.add(3);
      await _eventually(() => again.responses.length == 1, 'the echo after the cut');
      await again.requests.close();
      await again.done.future.timeout(const Duration(seconds: 5));
    });
    test('a cut ends a call the same way as on plain TCP', () async {
      // The same server without TLS, behind its own proxy.
      final _EchoService plainService = _EchoService();
      final Server plainServer = Server.create(services: <Service>[plainService]);
      await plainServer.serve(address: InternetAddress.loopbackIPv4, port: 0);
      final ChaosProxy plainProxy =
          await ChaosProxy.start('127.0.0.1', plainServer.port!);
      final ClientChannelBase plainChannel = proxiedGrpcChannel(
        proxyHost: plainProxy.host,
        proxyPort: plainProxy.port,
        serverName: serverName,
        ssl: false,
      );
      addTearDown(() async {
        await plainChannel.terminate();
        await plainProxy.close();
        await plainServer.shutdown();
      });

      /// Loses an answer (stallDown, cut), then a request (stallUp, cut); returns how the two calls ended and what
      /// the server received.
      Future<String> scenario(
          _EchoClient echo, ChaosProxy proxy, _EchoService service) async {
        final List<String> outcome = <String>[];
        for (final ChaosMode mode in <ChaosMode>[
          ChaosMode.stallDown,
          ChaosMode.stallUp,
        ]) {
          final _Call call = _Call(echo);
          call.requests.add(1);
          await _eventually(() => call.responses.length == 1, 'the first echo');
          proxy.mode = mode;
          call.requests.add(2);
          if (mode == ChaosMode.stallDown) {
            await _eventually(() => service.received.last == 2,
                'the request to reach the server');
          }
          await Future<void>.delayed(const Duration(milliseconds: 200));
          proxy
            ..cut()
            ..mode = ChaosMode.forward;
          await call.done.future.timeout(const Duration(seconds: 10));
          outcome.add('${mode.name}: code ${(call.error! as GrpcError).codeName}, '
              'responses ${call.responses}');
        }
        return '$outcome, received ${service.received}, '
            'connections ${proxy.acceptedConnections}, cuts ${proxy.cuts}';
      }

      final String overTls = await scenario(client(), proxy, service);
      final String overTcp =
          await scenario(_EchoClient(plainChannel), plainProxy, plainService);
      expect(overTls, overTcp);
      expect(overTls, contains('received [1, 2, 1]'));
      expect(overTls, contains('connections 2, cuts 2'));
      // ignore: avoid_print
      print('cut through the proxy, TLS and plain TCP alike: $overTls');
    });
  }, skip: skip);
}
